/* Feather Icons Font Mapping */
@font-face {
  font-family: 'feather';
  src: url('../fonts/Feather.woff') format('woff'),
       url('../fonts/Feather.ttf') format('truetype'),
       url('../fonts/Feather.svg#feather') format('svg');
  font-weight: normal;
  font-style: normal;
  font-display: block;
}

[class^="feather-"], [class*=" feather-"], .feather {
  font-family: 'feather' !important;
  speak: never;
  font-style: normal;
  font-weight: normal;
  font-variant: normal;
  text-transform: none;
  line-height: 1;
  display: inline-block;
  vertical-align: -0.125em;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

